function CC_makeOuvRowHtml(row,secSel,grip,dupBtn,delBtn){
  var rid=row.id;
  var oc="CC_onRowInput('ouv','"+rid+"')";
  var codePart='<div class="id-cell">'+grip+dupBtn+'<input type="text" class="tbl-input" value="'+(row.code||'')+'" oninput="CC_setRowProp(\'ouv\',\''+rid+'\',\'code\',this.value)" style="width:60px"></div>';
  var emplPart='<input type="text" class="tbl-input" value="'+(row.empl||'')+'" oninput="CC_setRowProp(\'ouv\',\''+rid+'\',\'empl\',this.value)" style="width:60px">';
  var qtyPart='<input type="text" class="tbl-input" value="'+(row.qty||1)+'" oninput="CC_setRowProp(\'ouv\',\''+rid+'\',\'qty\',this.value);'+oc+'" style="width:40px;text-align:center">';
  var lPart=CC_dimImpHtml('CC_l_pi_'+rid,'CC_l_po_'+rid,row.l_pi,row.l_po,oc)+CC_dimMmHtml('CC_l_mm_'+rid,row.l_mm,oc);
  var hPart=CC_dimImpHtml('CC_h_pi_'+rid,'CC_h_po_'+rid,row.h_pi,row.h_po,oc)+CC_dimMmHtml('CC_h_mm_'+rid,row.h_mm,oc);
  var jeuPart='<input type="text" class="tbl-input jeu-in" id="CC_jeu_'+rid+'" value="'+(row.jeu||0.5)+'" oninput="CC_setRowProp(\'ouv\',\''+rid+'\',\'jeu\',this.value);'+oc+'">';
  var surfPart='<span class="tbl-input computed col-surf" id="CC_surf_'+rid+'">—</span>';
  var perimPart='<span class="tbl-input computed col-perim" id="CC_perim_'+rid+'">—</span>';
  var sacsPart='<span class="tbl-input computed col-sacs" id="CC_sacs_'+rid+'">—</span>';
  return '<td>'+codePart+'</td>'
    +'<td>'+emplPart+'</td>'
    +'<td>'+qtyPart+'</td>'
    +'<td>'+lPart+'</td>'
    +'<td>'+hPart+'</td>'
    +'<td>'+jeuPart+'</td>'
    +'<td class="col-surf">'+surfPart+'</td>'
    +'<td class="col-perim">'+perimPart+'</td>'
    +'<td class="col-sacs">'+sacsPart+'</td>'
    +'<td><div class="row-actions">'+delBtn+'</div></td>';
}

function CC_makeSecSubTd(zone,secId,rows){
  var secRows=rows.filter(function(r){return r.secId===secId;});
  var totSurf=0,totSacs=0;
  secRows.forEach(function(r){
    // _surf et _sacs sont déjà des totaux de ligne (incluent la quantité).
    if(r._surf)totSurf+=r._surf;
    if(r._sacs)totSacs+=r._sacs;
  });
  var sec=CC_sections.find(function(s){return s.id===secId;})||{name:'?'};
  var surfTd='<td class="col-surf" style="text-align:right">'+CC_dispSurf(totSurf)+' '+CC_surfU()+'</td>';
  var sacsTd='<td class="col-sacs" style="text-align:right;font-weight:600">'+CC_fmtInt(totSacs)+'</td>';
  var lbl=function(cs){return '<td class="sec-sub-label" colspan="'+cs+'">Sous-total '+sec.name+'</td>';};
  // Le total des colonnes doit correspondre EXACTEMENT à l'en-tête de chaque zone,
  // sinon le tableau se désaligne (en-tête de section vs sous-total).
  if(zone==='pig'){
    // 12 col : Id, Qté, Type, Base1, Pente1, Base2, Pente2, Surf, Seg, Épais., Sacs, actions
    return lbl(7)+surfTd+'<td class="col-seg"></td><td></td>'+sacsTd+'<td></td>';
  }
  if(zone==='ouv'){
    // 10 col : Code, Empl., Qté, Largeur, Hauteur, Jeu, Surface, Périm., Sacs, actions
    return lbl(6)+surfTd+'<td class="col-perim"></td>'+sacsTd+'<td></td>';
  }
  // grenier / murs / plafonds : 9 col
  // Id, Qté, Longueur, Largeur|Hauteur, Surface, Valeur R, Épais., Sacs, actions
  return lbl(4)+surfTd+'<td class="col-r"></td><td class="col-ep"></td>'+sacsTd+'<td></td>';
}

// ─────────────────────────────────────────────────────────
//  ACTIONS RANGÉES
// ─────────────────────────────────────────────────────────
function CC_setRowProp(zone,id,prop,val){
  var row=(CC_rows[zone]||[]).find(function(r){return r.id===id;});
  if(row)row[prop]=val;
}
function CC_removeRow(zone,id){
  var rows=CC_rows[zone]||[];
  var gone=rows.find(function(r){return r.id===id;});
  CC_rows[zone]=rows.filter(function(r){return r.id!==id;});
  // Si la ligne provient d'une mesure du take-off, supprimer aussi cette mesure
  // (et les lignes sœurs issues de la même mesure) pour garder plan et tableau alignés.
  if(gone&&gone._gpmId!=null){
    var gid_=gone._gpmId;
    Object.keys(CC_rows).forEach(function(z){ CC_rows[z]=(CC_rows[z]||[]).filter(function(r){return r._gpmId!==gid_;}); });
    if(typeof window!=='undefined'&&typeof window.GPM_removeMeasureById==='function')window.GPM_removeMeasureById(gid_);
    CC_renderAllTables();
  } else {
    CC_renderTable(zone);
  }
  CC_recalc();
}
function CC_dupRow(zone,id){
  var rows=CC_rows[zone]||[];
  var idx=rows.findIndex(function(r){return r.id===id;});
  if(idx<0)return;
  var copy=JSON.parse(JSON.stringify(rows[idx]));
  copy.id=CC_newRowId();
  delete copy._gpmId; // la copie est une ligne indépendante, non liée à la mesure du plan
  rows.splice(idx+1,0,copy);
  CC_renderTable(zone);
  CC_recalc();
}
function CC_changeRowSec(zone,id,secId){
  CC_setRowProp(zone,id,'secId',secId);
  CC_renderTable(zone);
  CC_recalc();
}
function CC_setPigType(id,type){
  var row=(CC_rows.pig||[]).find(function(r){return r.id===id;});
  if(row)row.type=type;
  CC_renderTable('pig');
  CC_recalc();
}
function CC_onRowInput(zone,id){
  // Sync les dimensions depuis le DOM vers l'objet row. On NE touche PAS à row.surf :
  // la priorité dimensions-complètes / pi²-manuel est tranchée dans CC_rowSurf au
  // moment du calcul. Ainsi une dimension partielle n'efface pas un pi² saisi, et
  // des dimensions complètes priment automatiquement sur le pi².
  var row=(CC_rows[zone]||[]).find(function(r){return r.id===id;});
  if(!row)return;
  var g=function(sfx){var el=CC_gid('CC_'+sfx+'_'+id);return el?el.value:'';};
  if(zone==='grenier'||zone==='plafonds'){
    row.l_pi=g('l_pi');row.l_po=g('l_po');row.l_mm=g('l_mm');
    row.w_pi=g('w_pi');row.w_po=g('w_po');row.w_mm=g('w_mm');
  } else if(zone==='murs'){
    row.l_pi=g('l_pi');row.l_po=g('l_po');row.l_mm=g('l_mm');
    row.h_pi=g('h_pi');row.h_po=g('h_po');row.h_mm=g('h_mm');
    row.ep=CC_epCanonV(g('ep'))||row.ep;
  } else if(zone==='pig'){
    row.l1_pi=g('l1_pi');row.l1_po=g('l1_po');row.l1_mm=g('l1_mm');
    row.pente1=g('p1')||row.pente1;
    row.l2_pi=g('l2_pi');row.l2_po=g('l2_po');row.l2_mm=g('l2_mm');
    row.pente2=g('p2')||row.pente2;
    row.ep=CC_epCanonV(g('ep'))||row.ep;
  } else if(zone==='ouv'){
    row.l_pi=g('l_pi');row.l_po=g('l_po');row.l_mm=g('l_mm');
    row.h_pi=g('h_pi');row.h_po=g('h_po');row.h_mm=g('h_mm');
    row.jeu=g('jeu')||row.jeu;
  }
  CC_recalc();
}
// Saisie directe d'un pi² (écrasement) : stocké dans row.surf, utilisé tant que les
// deux dimensions ne sont pas saisies. Vider le champ rétablit le calcul par dimensions.
function CC_onSurfInput(zone,id,val){
  var row=(CC_rows[zone]||[]).find(function(r){return r.id===id;});
  if(!row)return;
  row.surf=(val==null?'':String(val)).trim();
  CC_recalc();
}

// ─────────────────────────────────────────────────────────
//  DRAG & DROP
// ─────────────────────────────────────────────────────────
var CC_dragSrc=null,CC_dragZone=null;
function CC_initDragDrop(zone){
  var tbody=CC_gid('CC_tbody_'+zone);
  if(!tbody)return;
  tbody.querySelectorAll('tr[data-rowid]').forEach(function(tr){
    tr.addEventListener('dragstart',function(e){
      CC_dragSrc=tr.getAttribute('data-rowid');
      CC_dragZone=zone;
      tr.classList.add('row-dragging');
      e.dataTransfer.effectAllowed='move';
    });
    tr.addEventListener('dragend',function(){
      tr.classList.remove('row-dragging');
      document.querySelectorAll('.drop-above,.drop-below,.drop-into').forEach(function(el){el.classList.remove('drop-above','drop-below','drop-into');});
    });
    tr.addEventListener('dragover',function(e){
      e.preventDefault();
      if(!CC_dragSrc)return;
      document.querySelectorAll('.drop-above,.drop-below').forEach(function(el){el.classList.remove('drop-above','drop-below');});
      var rect=tr.getBoundingClientRect();
      if(e.clientY<rect.top+rect.height/2) tr.classList.add('drop-above');
      else tr.classList.add('drop-below');
    });
    tr.addEventListener('drop',function(e){
      e.preventDefault();
      if(!CC_dragSrc||CC_dragZone!==zone)return;
      var rows=CC_rows[zone];
      var dragId=CC_dragSrc;
      var tgtId=tr.getAttribute('data-rowid');
      CC_dragSrc=null;
      if(dragId===tgtId)return;
      var srcIdx=rows.findIndex(function(r){return r.id===dragId;});
      if(srcIdx<0)return;
      var rect=tr.getBoundingClientRect();
      var after=e.clientY>=rect.top+rect.height/2;
      // La ligne déplacée adopte la section de la ligne cible.
      var tgtRow=rows.find(function(r){return r.id===tgtId;});
      var item=rows.splice(srcIdx,1)[0];
      if(tgtRow)item.secId=tgtRow.secId;
      // Recalcule l'index cible APRÈS le retrait (les indices ont pu se décaler).
      var tgtIdx=rows.findIndex(function(r){return r.id===tgtId;});
      if(tgtIdx<0){rows.push(item);}
      else{rows.splice(tgtIdx+(after?1:0),0,item);}
      CC_renderTable(zone);
      CC_recalc();
    });
  });
  // Sections headers drop
  tbody.querySelectorAll('.sec-group-head').forEach(function(tr){
    tr.addEventListener('dragover',function(e){e.preventDefault();tr.classList.add('drop-into');});
    tr.addEventListener('dragleave',function(){tr.classList.remove('drop-into');});
    tr.addEventListener('drop',function(e){
      e.preventDefault();
      tr.classList.remove('drop-into');
      if(!CC_dragSrc||CC_dragZone!==zone)return;
      var secId=tr.getAttribute('data-secid');
      CC_setRowProp(zone,CC_dragSrc,'secId',secId);
      CC_dragSrc=null;
      CC_renderTable(zone);
      CC_recalc();
    });
  });
  // Sous-totaux de section : aussi des cibles de drop (utile pour déposer dans une
  // section VIDE, dont l'en-tête est mince — le curseur tombe souvent sur le sous-total).
  tbody.querySelectorAll('.sec-group-sub').forEach(function(tr){
    tr.addEventListener('dragover',function(e){e.preventDefault();if(CC_dragSrc&&CC_dragZone===zone)tr.classList.add('drop-into');});
    tr.addEventListener('dragleave',function(){tr.classList.remove('drop-into');});
    tr.addEventListener('drop',function(e){
      e.preventDefault();
      tr.classList.remove('drop-into');
      if(!CC_dragSrc||CC_dragZone!==zone)return;
      var secId=tr.getAttribute('data-sec-sub');
      if(secId)CC_setRowProp(zone,CC_dragSrc,'secId',secId);
      CC_dragSrc=null;
      CC_renderTable(zone);
      CC_recalc();
    });
  });
  // Tab depuis le dernier champ saisissable d'une rangée → crée/cible la ligne suivante.
  // Listener délégué : on identifie au vol le dernier input non-readonly de la rangée.
  if(tbody.getAttribute('data-tabwired')!=='1'){
    tbody.setAttribute('data-tabwired','1');
    tbody.addEventListener('keydown',function(e){
      if(e.key!=='Tab'||e.shiftKey)return;
      var inp=e.target;
      if(!inp||inp.tagName!=='INPUT')return;
      var tr=inp.closest('tr[data-rowid]');
      if(!tr)return;
      // Liste des inputs réellement tabbables (visibles et non readonly) de la rangée.
      var inputs=Array.prototype.filter.call(tr.querySelectorAll('input'),function(el){
        if(el.readOnly||el.tabIndex===-1)return false;
        // exclut les champs masqués (dim-mm caché en imp, dim-imp caché en mm)
        return el.offsetParent!==null;
      });
      if(inputs.length&&inp===inputs[inputs.length-1]){
        e.preventDefault();
        var rid=tr.getAttribute('data-rowid');
        // Différé : on ne mute pas le tableau pendant l'événement keydown (sinon le
        // navigateur réinitialise le focus sur la 1re ligne quand l'input courant
        // est détruit par le re-render). On laisse l'événement se terminer d'abord.
        setTimeout(function(){CC_tabNext(zone,rid);},0);
      }
    });
  }
}

// ─────────────────────────────────────────────────────────
//  CONFIGURATION
// ─────────────────────────────────────────────────────────
// ─────────────────────────────────────────────────────────
//  CONFIGURATION (section 2)
//  Chaque zone : Épaisseur (po) ↔ Valeur R (liés) + Densité, chacun avec
//  saisie + slider. Toute modification s'applique IMMÉDIATEMENT à toutes les
//  rangées de la zone (plus de bouton « Appliquer »).
// ─────────────────────────────────────────────────────────
var CC_CFG_RANGE={
  grenier:{epMin:4,epMax:30,rMin:12,rMax:108,densMin:1,densMax:2},
  murs:{epMin:1,epMax:10,rMin:3,rMax:35,densMin:3,densMax:5},
  plafonds:{epMin:3.5,epMax:20.25,rMin:13,rMax:71,densMin:1,densMax:3}
};
function CC_cfgSuffix(zone){return zone==='grenier'?'Grenier':(zone==='murs'?'Murs':'Plafonds');}
function CC_cfgIds(zone){
  var s=CC_cfgSuffix(zone);
  return {epTxt:'CC_cfg'+s+'Ep',epSld:'CC_cfg'+s+'EpSlider',
          rTxt:'CC_cfg'+s+'R',rSld:'CC_cfg'+s+'RSlider',
          densTxt:'CC_cfg'+s+'Dens',densSld:'CC_cfg'+s+'DensSlider'};
}
// Interdépendance tenant compte de la densité (les murs ajustent R selon densité).
function CC_ep2R_d(zone,ep,dens){
  if(zone==='murs')return CC_rForMurEpDens(ep,dens);
  return CC_interpEp2R(zone,ep);
}
function CC_r2Ep_d(zone,r,dens){
  if(zone==='murs'){var adj=1+(dens-3.5)*0.04;return CC_interpR2Ep('murs',adj>0?r/adj:r);}
  return CC_interpR2Ep(zone,r);
}
// Handler unique des champs/sliders de config.
// src ∈ {epTxt,epSld,rTxt,rSld,densTxt,densSld}
function CC_onCfgInput(zone,src){
  var ids=CC_cfgIds(zone),rng=CC_CFG_RANGE[zone];
  var clamp=function(v,a,b){return Math.max(a,Math.min(b,v));};
  var g=function(id){var e=CC_gid(id);return e?e.value:'';};
  var dens=clamp(src==='densSld'?CC_pf(g(ids.densSld)):CC_fldDens(ids.densTxt),rng.densMin,rng.densMax);
  var ep,r;
  if(src==='rTxt'||src==='rSld'){
    r=clamp(src==='rSld'?CC_pf(g(ids.rSld)):CC_fldR(ids.rTxt),rng.rMin,rng.rMax);
    ep=clamp(CC_r2Ep_d(zone,r,dens),rng.epMin,rng.epMax);
  } else {
    // ep* ou dens* : l'épaisseur pilote, R (re)calculé (dépend de la densité pour les murs)
    ep=clamp(src==='epSld'?CC_pf(g(ids.epSld)):CC_fldEp(ids.epTxt),rng.epMin,rng.epMax);
    r=clamp(CC_ep2R_d(zone,ep,dens),rng.rMin,rng.rMax);
  }
  CC_applyCfgValues(zone,ep,r,dens,src);
}
// Met à jour les contrôles (sauf celui en cours d'édition) puis applique aux rangées.
function CC_applyCfgValues(zone,ep,r,dens,src){
  var ids=CC_cfgIds(zone);
  // Mise à jour ciblée (on ne réécrit pas le contrôle actif)
  if(src!=='epTxt'){var a=CC_gid(ids.epTxt);if(a)a.value=CC_epDispV(ep);}
  if(src!=='epSld'){var b=CC_gid(ids.epSld);if(b)b.value=ep;}
  if(src!=='rTxt'){var c=CC_gid(ids.rTxt);if(c)c.value=CC_rDispV(r);}
  if(src!=='rSld'){var d=CC_gid(ids.rSld);if(d)d.value=Math.round(r);}
  if(src!=='densTxt'){var e=CC_gid(ids.densTxt);if(e)e.value=CC_densDispV(dens);}
  if(src!=='densSld'){var f=CC_gid(ids.densSld);if(f)f.value=dens;}
  CC_pushCfgToRows(zone,ep,r,dens);
  CC_recalc();
}
// Auto-applique les valeurs de config à TOUTES les rangées de la zone.
function CC_pushCfgToRows(zone,ep,r,dens){
  if(zone==='grenier'){
    CC_rows.grenier.forEach(function(row){row.rVal=r;row.ep=ep;row.dens=dens;});
    CC_renderTable('grenier');
  } else if(zone==='plafonds'){
    CC_rows.plafonds.forEach(function(row){row.ht=ep;row.dens=dens;});
    CC_renderTable('plafonds');
  } else if(zone==='murs'){
    CC_rows.murs.forEach(function(row){row.ep=ep;row.dens=dens;});
    CC_rows.pig.forEach(function(row){row.ep=ep;row.dens=dens;});
    CC_renderTable('murs');CC_renderTable('pig');
  }
}
// Lecture des valeurs de config courantes (pour les nouvelles rangées).
function CC_cfgVal(zone,which){
  var ids=CC_cfgIds(zone);
  var rng=CC_CFG_RANGE[zone];
  var clamp=function(v,a,b){return Math.max(a,Math.min(b,v));};
  if(which==='ep')return clamp(CC_fldEp(ids.epTxt),rng.epMin,rng.epMax);
  if(which==='r')return clamp(CC_fldR(ids.rTxt),rng.rMin,rng.rMax);
  return clamp(CC_fldDens(ids.densTxt),rng.densMin,rng.densMax);
}
function CC_initCfg(){
  // Grenier piloté par R (R60 par défaut → ép dérivée) ; murs/plafonds pilotés par ép.
  CC_onCfgInput('grenier','rTxt');
  CC_onCfgInput('murs','epTxt');
  CC_onCfgInput('plafonds','epTxt');
}


// ─────────────────────────────────────────────────────────
//  SLIDERS LIÉS R ↔ ÉPAISSEUR (en-tête de zone)
//  Deux sliders couplés : bouger l'un ajuste l'autre via la table PROFIB CELL.
//  Plages par zone (bornes de la table).
// ─────────────────────────────────────────────────────────
var CC_SLIDER_RANGE={
  grenier:{rMin:12,rMax:108,epMin:4,epMax:30},
  plafonds:{rMin:13,rMax:71,epMin:3.5,epMax:20.25},
  murs:{rMin:3,rMax:35,epMin:1,epMax:10},
  pig:{rMin:3,rMax:35,epMin:1,epMax:10}
};
// Convertit l'épaisseur d'une zone en R (les murs/pignons tiennent compte de la densité).
function CC_zoneEp2R(zone,ep){
  if(zone==='murs'||zone==='pig'){
    var d=CC_fldDens(zone==='pig'?'CC_pigDens':'CC_mursDens')||4.0;
    return CC_rForMurEpDens(ep,d);
  }
  return CC_interpEp2R(zone,ep);
}
function CC_zoneR2Ep(zone,r){
  if(zone==='murs'||zone==='pig'){
    var d=CC_fldDens(zone==='pig'?'CC_pigDens':'CC_mursDens')||4.0;
    var adj=1+(d-3.5)*0.04;
    return CC_interpR2Ep('murs',adj>0?r/adj:r);
  }
  return CC_interpR2Ep(zone,r);
}
// IDs des contrôles par zone : champ R, champ ép, slider R, slider ép, label R calculé.
function CC_sliderIds(zone){
  if(zone==='grenier')return {rTxt:'CC_grenierR',epTxt:'CC_grenierEp',rSld:'CC_grenierRSlider',epSld:'CC_grenierEpSlider'};
  if(zone==='plafonds')return {rTxt:'CC_plafondR',epTxt:'CC_plafondHt',rSld:'CC_plafondRSlider',epSld:'CC_plafondEpSlider'};
  if(zone==='murs')return {rTxt:'CC_mursRHdr',epTxt:'CC_mursEp',rSld:'CC_mursRSlider',epSld:'CC_mursEpSlider'};
  if(zone==='pig')return {rTxt:'CC_pigRHdr',epTxt:'CC_pigEp',rSld:'CC_pigRSlider',epSld:'CC_pigEpSlider'};
  return null;
}
// Synchronise sliders + champs à partir d'une source ('rTxt'|'epTxt'|'rSld'|'epSld').
// rFromEp : si vrai, R est calculé (champ R en lecture seule, ex. plafonds/murs).
function CC_syncZoneSliders(zone,src){
  var ids=CC_sliderIds(zone);if(!ids)return;
  var rng=CC_SLIDER_RANGE[zone];
  var clamp=function(v,a,b){return Math.max(a,Math.min(b,v));};
  var rEl=CC_gid(ids.rTxt),epEl=CC_gid(ids.epTxt),rSl=CC_gid(ids.rSld),epSl=CC_gid(ids.epSld);
  var r,ep; // toujours en canonique impérial (R, pouces)
  if(src==='rSld'||src==='rTxt'){
    // slider = impérial brut ; champ texte = unité courante → canonique
    r=clamp(src==='rSld'?CC_pf(rSl?rSl.value:0):CC_rCanonV(rEl?rEl.value:0),rng.rMin,rng.rMax);
    ep=clamp(CC_zoneR2Ep(zone,r),rng.epMin,rng.epMax);
  } else {
    ep=clamp(src==='epSld'?CC_pf(epSl?epSl.value:0):CC_epCanonV(epEl?epEl.value:0),rng.epMin,rng.epMax);
    r=clamp(CC_zoneEp2R(zone,ep),rng.rMin,rng.rMax);
  }
  // Sliders : valeur impériale brute. Champs texte : affichage en unité courante.
  if(rSl&&src!=='rSld')rSl.value=r;
  if(epSl&&src!=='epSld')epSl.value=ep;
  if(rEl&&src!=='rTxt'){
    if(zone==='grenier')rEl.value=CC_rDispV(r);            // éditable : nombre seul
    else rEl.value=(CC_unitSystem==='mm'?'RSI-'+CC_fmt(r/CC_R_TO_RSI,2):'R-'+Math.round(r)); // calculé
  }
  if(epEl&&src!=='epTxt')epEl.value=CC_epDispV(ep);
  CC_pushZoneHeaderToRows(zone,r,ep);
  CC_recalc();
}
// Applique R/ép de l'en-tête aux données de rangées de la zone.
function CC_pushZoneHeaderToRows(zone,r,ep){
  var setEp=function(row){var el=CC_gid('CC_ep_'+row.id);if(el&&document.activeElement!==el)el.value=CC_epDispV(ep);};
  if(zone==='grenier'){
    var dg=CC_fldDens('CC_grenierDens')||1.52;
    CC_rows.grenier.forEach(function(row){row.rVal=r;row.ep=ep;row.dens=dg;});
  } else if(zone==='plafonds'){
    var dpl=CC_fldDens('CC_plafondDens')||2.0;
    CC_rows.plafonds.forEach(function(row){row.ht=ep;row.dens=dpl;});
  } else if(zone==='murs'){
    var dm=CC_fldDens('CC_mursDens')||4.0;
    CC_rows.murs.forEach(function(row){row.ep=ep;row.dens=dm;setEp(row);});
  } else if(zone==='pig'){
    var dp=CC_fldDens('CC_pigDens')||4.0;
    CC_rows.pig.forEach(function(row){row.ep=ep;row.dens=dp;setEp(row);});
  }
}

function CC_onZoneHeaderChange(zone){
  // Saisie dans un champ d'en-tête → synchronise l'autre champ + les sliders liés.
  CC_syncZoneDensSlider(zone);
  if(zone==='grenier'){CC_syncZoneSliders('grenier','rTxt');return;}
  if(zone==='plafonds'){CC_syncZoneSliders('plafonds','epTxt');return;}
  if(zone==='murs'){CC_syncZoneSliders('murs','epTxt');return;}
  if(zone==='pig'){CC_syncZoneSliders('pig','epTxt');return;}
  CC_recalc();
}
function CC_onZoneHeaderEpChange(zone){
  // Saisie dans le champ épaisseur → synchronise R + sliders.
  CC_syncZoneSliders(zone,'epTxt');
}
function CC_applyZoneHeaderAll(zone){
  if(zone==='grenier'){
    var r=CC_fldR('CC_grenierR')||60;
    var d=CC_fldDens('CC_grenierDens')||1.52;
    CC_rows.grenier.forEach(function(row){row.rVal=r;row.dens=d;});
    CC_renderTable('grenier');
  } else if(zone==='plafonds'){
    var ht=CC_fldEp('CC_plafondHt')||11.875;
    var d=CC_fldDens('CC_plafondDens')||2.0;
    CC_rows.plafonds.forEach(function(row){row.ht=ht;row.dens=d;});
    CC_renderTable('plafonds');
  } else if(zone==='murs'){
    var ep=CC_fldEp('CC_mursEp')||5.5;
    var d=CC_fldDens('CC_mursDens')||4.0;
    CC_rows.murs.forEach(function(row){row.ep=ep;row.dens=d;});
    CC_renderTable('murs');
  }
  CC_recalc();
}
function CC_onHauteurGlobalInput(){
  CC_recalc();
}
function CC_applyHauteurAll(){
  var hPo=CC_readDim('CC_hauteurGlobal_pi','CC_hauteurGlobal_po','CC_hauteurGlobal_mm');
  CC_rows.murs.forEach(function(row){
    row.h_pi=Math.floor(hPo/12)||'';
    row.h_po=(hPo%12)||'';
    row.h_mm=CC_inToMm(hPo)||'';
  });
  CC_renderTable('murs');
  CC_recalc();
}
function CC_onMursEpInput(){
  // Saisie directe de l'épaisseur murs → synchronise R + sliders + rangées.
  CC_syncZoneSliders('murs','epTxt');
}
// Handler appelé par les <input type="range"> des en-têtes de zone.
// which : 'r' (slider valeur R) ou 'ep' (slider épaisseur).
function CC_onZoneSlider(zone,which){
  CC_syncZoneSliders(zone,which==='r'?'rSld':'epSld');
}
// Slider de densité (impérial) → champ texte en unité courante puis recalcul.
function CC_onZoneDensSlider(zone){
  var sId=zone==='grenier'?'CC_grenierDensSlider':(zone==='murs'?'CC_mursDensSlider':(zone==='pig'?'CC_pigDensSlider':'CC_plafondDensSlider'));
  var tId=zone==='grenier'?'CC_grenierDens':(zone==='murs'?'CC_mursDens':(zone==='pig'?'CC_pigDens':'CC_plafondDens'));
  var sl=CC_gid(sId),tx=CC_gid(tId);
  if(sl&&tx)tx.value=CC_densDispV(CC_pf(sl.value)); // slider impérial → affichage
  CC_onZoneHeaderChange(zone);
}
// Champ densité (unité courante) → slider (impérial).
function CC_syncZoneDensSlider(zone){
  var sId=zone==='grenier'?'CC_grenierDensSlider':(zone==='murs'?'CC_mursDensSlider':(zone==='pig'?'CC_pigDensSlider':'CC_plafondDensSlider'));
  var tId=zone==='grenier'?'CC_grenierDens':(zone==='murs'?'CC_mursDens':(zone==='pig'?'CC_pigDens':'CC_plafondDens'));
  var sl=CC_gid(sId),tx=CC_gid(tId);
  if(sl&&tx&&document.activeElement!==sl){var v=CC_densCanonV(tx.value);if(v>0)sl.value=v;}
}
function CC_applyEpMursAll(){
  CC_onMursEpInput();
}
function CC_applyEpPigAll(){
  CC_syncZoneSliders('pig','epTxt');
}
function CC_onJeuGlobalInput(){CC_recalc();}
function CC_applyJeuAll(){
  var jeu=CC_pf(CC_gid('CC_jeuGlobal')?CC_gid('CC_jeuGlobal').value:0.5)||0.5;
  CC_rows.ouv.forEach(function(row){row.jeu=jeu;var el=CC_gid('CC_jeu_'+row.id);if(el)el.value=jeu;});
  CC_recalc();
}

// ─────────────────────────────────────────────────────────
//  COLONNES TOGGLABLES
// ─────────────────────────────────────────────────────────
function CC_toggleCol(zone,col,show){
  var tbl=CC_gid('CC_tbl_'+zone);
  if(!tbl)return;
  if(show) tbl.classList.remove('gp-hide-'+col);
  else tbl.classList.add('gp-hide-'+col);
}

// ─────────────────────────────────────────────────────────
//  BUFFER
// ─────────────────────────────────────────────────────────
function CC_getBuf(){
  var v=CC_pf(CC_gid('CC_bufInput')?CC_gid('CC_bufInput').value:'5');
  return isNaN(v)?5:Math.max(0,Math.min(30,v));
}
function CC_syncBuffer(src){
  var v;
  if(src==='slider') v=CC_pf(CC_gid('CC_bufSlider').value);
  else if(src==='summary-slider') v=CC_pf(CC_gid('CC_sBufSlider').value);
  else if(src==='input') v=CC_pf(CC_gid('CC_bufInput').value);
  else v=CC_pf(CC_gid('CC_sBufInput').value);
  v=Math.max(0,Math.min(30,isNaN(v)?5:v));
  ['CC_bufSlider','CC_sBufSlider'].forEach(function(id){var el=CC_gid(id);if(el)el.value=v;});
  ['CC_bufInput','CC_sBufInput'].forEach(function(id){var el=CC_gid(id);if(el)el.value=v;});
  var disp=CC_gid('CC_sBufDisplay');if(disp)disp.textContent=v+'%';
  CC_recalc();
}
function CC_clampBuffer(){
  var v=CC_getBuf();
  ['CC_bufSlider','CC_sBufSlider'].forEach(function(id){var el=CC_gid(id);if(el)el.value=v;});
  ['CC_bufInput','CC_sBufInput'].forEach(function(id){var el=CC_gid(id);if(el)el.value=v;});
  var disp=CC_gid('CC_sBufDisplay');if(disp)disp.textContent=v+'%';
}

// ─────────────────────────────────────────────────────────
//  CALCUL PRINCIPAL
// ─────────────────────────────────────────────────────────
function CC_recalc(){
  var buf=CC_getBuf()/100;
  var totGrenier=0,totPlafonds=0,totMurs=0,totPig=0,totOuv=0;
  var totSurfGrenier=0,totSurfPlafonds=0,totSurfMurs=0;

  // GRENIER
  var grenierR=CC_fldR('CC_grenierR')||60;
  var grenierDens=CC_fldDens('CC_grenierDens')||1.52;
  var grenierEp=CC_interpR2Ep('grenier',grenierR);
  var grenierEpEl=CC_gid('CC_grenierEp');
  if(grenierEpEl&&document.activeElement!==grenierEpEl)grenierEpEl.value=CC_epDispV(grenierEp);

  CC_rows.grenier.forEach(function(row){
    var qty=Math.max(1,CC_pf(row.qty)||1);
    var res=CC_rowSurf(row,'lw');
    var lineSurf=res.surf*qty;        // surface de la ligne = aire × quantité
    row._surf=lineSurf;
    var rRow=row.rVal||grenierR;
    var dRow=row.dens||grenierDens;
    var epRow=CC_interpR2Ep('grenier',rRow);
    var sacs=CC_sacsForSurf('grenier',lineSurf,epRow,dRow);
    row._sacs=sacs;row._rCalc=rRow;row._epCalc=epRow;row._densCalc=dRow;
    var surfEl=CC_gid('CC_surf_'+row.id);
    if(surfEl&&res.fromDims&&document.activeElement!==surfEl)surfEl.value=lineSurf?CC_dispSurf(lineSurf):'';
    var rEl=CC_gid('CC_r_'+row.id);if(rEl)rEl.value=CC_dispR(rRow);
    var epEl=CC_gid('CC_ep_'+row.id);if(epEl)epEl.value=CC_dispEp(epRow);
    var sacsEl=CC_gid('CC_sacs_'+row.id);if(sacsEl)sacsEl.textContent=CC_fmtInt(sacs);
    totGrenier+=sacs;
    totSurfGrenier+=lineSurf;
  });

  // PLAFONDS
  var plafondHt=CC_fldEp('CC_plafondHt')||11.875;
  var plafondDens=CC_fldDens('CC_plafondDens')||2.0;
  var plafondR=CC_interpEp2R('plafonds',plafondHt);
  var plafREl=CC_gid('CC_plafondR');if(plafREl)plafREl.value=(CC_unitSystem==='mm'?'RSI-'+CC_fmt(plafondR/CC_R_TO_RSI,2):'R-'+Math.round(plafondR));

  CC_rows.plafonds.forEach(function(row){
    var qty=Math.max(1,CC_pf(row.qty)||1);
    var res=CC_rowSurf(row,'lw');
    var lineSurf=res.surf*qty;
    row._surf=lineSurf;
    var htRow=row.ht||plafondHt;
    var dRow=row.dens||plafondDens;
    var rRow=CC_interpEp2R('plafonds',htRow);
    var sacs=CC_sacsForSurf('plafonds',lineSurf,htRow,dRow);
    row._sacs=sacs;row._rCalc=rRow;row._epCalc=htRow;row._densCalc=dRow;
    var surfEl=CC_gid('CC_surf_'+row.id);if(surfEl&&res.fromDims&&document.activeElement!==surfEl)surfEl.value=lineSurf?CC_dispSurf(lineSurf):'';
    var rEl=CC_gid('CC_r_'+row.id);if(rEl)rEl.value=CC_dispR(rRow);
    var epEl=CC_gid('CC_ep_'+row.id);if(epEl)epEl.value=CC_dispEp(htRow);
    var sacsEl=CC_gid('CC_sacs_'+row.id);if(sacsEl)sacsEl.textContent=CC_fmtInt(sacs);
    totPlafonds+=sacs;
    totSurfPlafonds+=lineSurf;
  });

  // MURS
  CC_rows.murs.forEach(function(row){
    var qty=Math.max(1,CC_pf(row.qty)||1);
    var res=CC_rowSurf(row,'lh');
    var lineSurf=res.surf*qty;
    row._surf=lineSurf;
    var epRow=CC_pf(row.ep)||5.5;
    var dRow=CC_pf(row.dens)||4.0;
    var rRow=CC_rForMurEpDens(epRow,dRow);
    var sacs=CC_sacsForSurf('murs',lineSurf,epRow,dRow);
    row._sacs=sacs;row._rCalc=rRow;row._epCalc=epRow;row._densCalc=dRow;
    var surfEl=CC_gid('CC_surf_'+row.id);if(surfEl&&res.fromDims&&document.activeElement!==surfEl)surfEl.value=lineSurf?CC_dispSurf(lineSurf):'';
    var rEl=CC_gid('CC_r_'+row.id);if(rEl)rEl.textContent=CC_dispR(rRow);
    var sacsEl=CC_gid('CC_sacs_'+row.id);if(sacsEl)sacsEl.textContent=CC_fmtInt(sacs);
    totMurs+=sacs;
    totSurfMurs+=lineSurf;
  });

  // PIGNONS
  CC_rows.pig.forEach(function(row){
    var qty=Math.max(1,CC_pf(row.qty)||1);
    var l1,l2=0,p1=CC_pf(row.pente1)||6,p2=CC_pf(row.pente2)||6;
    if(CC_unitSystem==='mm'){l1=CC_mmToIn(CC_pf(row.l1_mm));l2=CC_mmToIn(CC_pf(row.l2_mm));}
    else{l1=(CC_pf(row.l1_pi)||0)*12+(CC_pf(row.l1_po)||0);l2=(CC_pf(row.l2_pi)||0)*12+(CC_pf(row.l2_po)||0);}
    l1/=12;l2/=12; // en pieds
    var surf=0,seg=0;
    var directSurf=(!l1&&!l2&&row.surf!==''&&row.surf!=null&&CC_pf(row.surf)>0)?CC_pf(row.surf):0;
    if(directSurf>0){
      surf=directSurf; seg=0; // surface injectée (take-off) : pas de segment de pente
    } else if(row.type==='mono'){
      // Monopente : base = l1, hauteur au faîte h = base * pente/12, triangle = base*h/2
      var h=l1*(p1/12);
      surf=l1*h/2;
      seg=Math.sqrt(l1*l1+h*h);
    } else if(row.type==='centre'){
      // Centré (symétrique) : le faîte est au milieu de la base l1.
      // demi-base = l1/2, hauteur h = demi*pente/12, surface = base*h/2 (deux versants).
      var demi=l1/2,hc=demi*(p1/12);
      surf=l1*hc/2;
      seg=Math.sqrt(demi*demi+hc*hc)*2;
    } else {
      // Décentré : deux versants de bases l1 et l2 avec pentes p1 et p2.
      // h1 = l1*p1/12, h2 = l2*p2/12, surface = (l1+l2) * hMoy/2.
      var h1=l1*(p1/12),h2=l2*(p2/12),hMoy=(h1+h2)/2;
      surf=(l1+l2)*hMoy/2;
      seg=Math.sqrt(l1*l1+h1*h1)+Math.sqrt(l2*l2+h2*h2);
    }
    var lineSurf=surf*qty;
    row._surf=lineSurf;
    var epRow=CC_pf(row.ep)||5.5;
    var dRow=CC_pf(row.dens)||4.0;
    var sacs=CC_sacsForSurf('murs',lineSurf,epRow,dRow);
    row._sacs=sacs;row._seg=seg;row._rCalc=CC_rForMurEpDens(epRow,dRow);row._epCalc=epRow;row._densCalc=dRow;
    var surfEl=CC_gid('CC_surf_'+row.id);if(surfEl)surfEl.textContent=CC_dispSurf(lineSurf);
    var segEl=CC_gid('CC_seg_'+row.id);if(segEl)segEl.textContent=CC_dispLenFt(seg);
    var sacsEl=CC_gid('CC_sacs_'+row.id);if(sacsEl)sacsEl.textContent=CC_fmtInt(sacs);
    totPig+=sacs;
    totSurfMurs+=lineSurf;
  });

  // OUVERTURES — retrancher des murs
  CC_rows.ouv.forEach(function(row){
    var qty=Math.max(1,CC_pf(row.qty)||1);
    var jeu=CC_pf(row.jeu)||0.5;
    var l_po,h_po;
    if(CC_unitSystem==='mm'){l_po=CC_mmToIn(CC_pf(row.l_mm));h_po=CC_mmToIn(CC_pf(row.h_mm));}
    else{l_po=(CC_pf(row.l_pi)||0)*12+(CC_pf(row.l_po)||0);h_po=(CC_pf(row.h_pi)||0)*12+(CC_pf(row.h_po)||0);}
    // Une ouverture n'est comptée que si ses deux dimensions sont saisies, sinon le
    // jeu (0,5 po de chaque côté) gonflerait une rangée vide à 1×1 → faux « -1 sac ».
    var surf,perim;
    var sb=CC_pf(row.surfBase)||0, pb=CC_pf(row.perimBase)||0;
    if(sb>0){
      // ouverture tracée (forme libre / ronde) : aire + (périmètre × jeu)
      surf=sb+pb*(jeu/12); perim=pb;
    } else if(l_po>0&&h_po>0){
      var lTot=l_po+2*jeu,hTot=h_po+2*jeu;
      surf=CC_surfFromDims(lTot,hTot);
      perim=2*(lTot+hTot)/12;
    } else { surf=0; perim=0; }
    var lineSurf=surf*qty;
    row._surf=lineSurf;row._perim=perim*qty;row._lpo=l_po;row._hpo=h_po;row._jeu=jeu;
    // Sacs à retrancher (en utilisant l'épaisseur moyenne des murs)
    var epMurs=CC_fldEp('CC_mursEp')||5.5;
    var dMurs=CC_fldDens('CC_mursDens')||4.0;
    var sacs=CC_sacsForSurf('murs',lineSurf,epMurs,dMurs);
    row._sacs=sacs;
    var surfEl=CC_gid('CC_surf_'+row.id);if(surfEl)surfEl.textContent=CC_dispSurf(lineSurf);
    var perimEl=CC_gid('CC_perim_'+row.id);if(perimEl)perimEl.textContent=CC_dispLenFt(perim*qty);
    var sacsEl=CC_gid('CC_sacs_'+row.id);if(sacsEl)sacsEl.textContent=lineSurf>0?'-'+CC_fmtInt(sacs):'0';
    totOuv+=sacs;
  });

  // Sous-totaux
  var stGr=CC_gid('CC_stSurfGrenier');if(stGr)stGr.textContent=CC_dispSurf(totSurfGrenier);
  var stGrS=CC_gid('CC_stSacsGrenier');if(stGrS)stGrS.textContent=CC_fmtInt(totGrenier);
  var stPl=CC_gid('CC_stSurfPlafonds');if(stPl)stPl.textContent=CC_dispSurf(totSurfPlafonds);
  var stPlS=CC_gid('CC_stSacsPlafonds');if(stPlS)stPlS.textContent=CC_fmtInt(totPlafonds);
  var stMu=CC_gid('CC_stSurfMurs');if(stMu)stMu.textContent=CC_dispSurf(totSurfMurs);
  var stMuS=CC_gid('CC_stSacsMurs');if(stMuS)stMuS.textContent=CC_fmtInt(totMurs+totPig);
  var stOvS=CC_gid('CC_stSacsOuv');if(stOvS)stOvS.textContent='-'+CC_fmtInt(totOuv);
  var stPgS=CC_gid('CC_stSacsPig');if(stPgS)stPgS.textContent=CC_fmtInt(totPig);

  var netMursTotal=Math.max(0,totMurs+totPig-totOuv);
  var netTotal=totGrenier+totPlafonds+netMursTotal;
  var bufTotal=Math.ceil(netTotal*(1+buf));
  var palTotal=Math.ceil(bufTotal/42);

  // Section matériaux
  var rGr=CC_gid('CC_resGrenier');if(rGr)rGr.textContent=CC_fmtInt(totGrenier);
  var rGs=CC_gid('CC_resGrenierSurf');if(rGs)rGs.textContent=CC_dispSurf(totSurfGrenier)+' '+CC_surfU();
  var rPl=CC_gid('CC_resPlafonds');if(rPl)rPl.textContent=CC_fmtInt(totPlafonds);
  var rPs=CC_gid('CC_resPlafondsSurf');if(rPs)rPs.textContent=CC_dispSurf(totSurfPlafonds)+' '+CC_surfU();
  var rMu=CC_gid('CC_resMurs');if(rMu)rMu.textContent=CC_fmtInt(netMursTotal);
  var rMs=CC_gid('CC_resMursSurf');if(rMs)rMs.textContent=CC_dispSurf(totSurfMurs)+' '+CC_surfU();
  var rNet=CC_gid('CC_resCellSacNet');if(rNet)rNet.textContent=CC_fmtInt(netTotal);
  var rBuf=CC_gid('CC_resCellSacBuf');if(rBuf)rBuf.textContent=String(bufTotal);
  var rPal=CC_gid('CC_resCellPal');if(rPal)rPal.textContent=String(palTotal);

  // Summary sidebar
  var totSurf=totSurfGrenier+totSurfPlafonds+totSurfMurs;
  var hS=CC_gid('CC_heroSacs');if(hS)hS.textContent=String(bufTotal);
  var hSurf=CC_gid('CC_heroSurf');if(hSurf)hSurf.textContent=CC_dispSurf(totSurf)+' '+CC_surfU();
  var hP=CC_gid('CC_heroPal');if(hP)hP.textContent=palTotal+' pal.';
  var sGr=CC_gid('CC_sumGrenier');if(sGr)sGr.textContent=CC_fmtInt(totGrenier);
  var sGrs=CC_gid('CC_sumSubGrenier');if(sGrs)sGrs.textContent=CC_dispSurf(totSurfGrenier)+' '+CC_surfU();
  var sPl=CC_gid('CC_sumPlafonds');if(sPl)sPl.textContent=CC_fmtInt(totPlafonds);
  var sPls=CC_gid('CC_sumSubPlafonds');if(sPls)sPls.textContent=CC_dispSurf(totSurfPlafonds)+' '+CC_surfU();
  var sMu=CC_gid('CC_sumMurs');if(sMu)sMu.textContent=CC_fmtInt(netMursTotal);
  var sMus=CC_gid('CC_sumSubMurs');if(sMus)sMus.textContent=CC_dispSurf(totSurfMurs)+' '+CC_surfU();
  var tN=CC_gid('CC_totSacsNet');if(tN)tN.textContent=CC_fmtInt(netTotal);
  var tP=CC_gid('CC_totPal');if(tP)tP.textContent=String(palTotal);
  var tB=CC_gid('CC_totSacsBuf');if(tB)tB.textContent=String(bufTotal);

  // Éléments Odoo
  var bagN=CC_gid('CC_bags_num');if(bagN)bagN.textContent=CC_fmtInt(netTotal);
  var metaS=CC_gid('CC_meta_surplus');if(metaS)metaS.textContent=String(bufTotal);

  // Récap sections
  CC_updateSectionRecap(totGrenier,totPlafonds,netMursTotal);

  // Sous-totaux sections dans les tables
  if(CC_sections.length>1){
    ['grenier','plafonds','murs','pig','ouv'].forEach(function(zone){
      CC_sections.forEach(function(sec){
        var subTr=document.querySelector('#CC_tbody_'+zone+' tr[data-sec-sub="'+sec.id+'"]');
        if(subTr)subTr.innerHTML=CC_makeSecSubTd(zone,sec.id,CC_rows[zone]);
      });
    });
  }
}

function CC_updateSectionRecap(gr,pl,mu){
  var card=CC_gid('CC_sectionRecapCard');
  if(!card)return;
  if(CC_sections.length<2){card.style.display='none';return;}
  card.style.display='';
  var div=CC_gid('CC_sectionRecap');
  if(!div)return;
  var html='<table class="sec-recap-table"><thead><tr><th>Section</th><th>Entretoit</th><th>Plafond</th><th>Murs</th><th>Total</th></tr></thead><tbody>';
  var totGr=0,totPl=0,totMu=0;
  CC_sections.forEach(function(sec){
    var sgr=0,spl=0,smu=0;
    ['grenier'].forEach(function(z){
      (CC_rows[z]||[]).filter(function(r){return r.secId===sec.id;}).forEach(function(r){sgr+=(r._sacs||0)*(CC_pf(r.qty)||1);});
    });
    ['plafonds'].forEach(function(z){
      (CC_rows[z]||[]).filter(function(r){return r.secId===sec.id;}).forEach(function(r){spl+=(r._sacs||0)*(CC_pf(r.qty)||1);});
    });
    ['murs','pig'].forEach(function(z){
      (CC_rows[z]||[]).filter(function(r){return r.secId===sec.id;}).forEach(function(r){smu+=(r._sacs||0)*(CC_pf(r.qty)||1);});
    });
    var tot=sgr+spl+smu;
    totGr+=sgr;totPl+=spl;totMu+=smu;
    html+='<tr><td class="sec-recap-name">'+sec.name+'</td><td>'+CC_fmtInt(sgr)+'</td><td>'+CC_fmtInt(spl)+'</td><td>'+CC_fmtInt(smu)+'</td><td><strong>'+CC_fmtInt(tot)+'</strong></td></tr>';
  });
  html+='</tbody><tfoot><tr class="sec-recap-total"><td>Total</td><td>'+CC_fmtInt(totGr)+'</td><td>'+CC_fmtInt(totPl)+'</td><td>'+CC_fmtInt(totMu)+'</td><td>'+CC_fmtInt(totGr+totPl+totMu)+'</td></tr></tfoot></table>';
  div.innerHTML=html;
}

// ─────────────────────────────────────────────────────────
//  STICKY HEADERS
//  (le scroll horizontal est contenu dans .table-wrap, ce qui empêche un sticky
//   CSS lié au scroll de page ; on clone donc l'en-tête dans un élément fixe.)
//  L'en-tête flottant n'est affiché que tant que la table est ENCORE traversée
//  par la ligne de base du menu (top < mb && bottom > mb) — il se retire dès
//  qu'on a dépassé la section.
// ─────────────────────────────────────────────────────────
var CC_STICKY_TYPES=['grenier','plafonds','murs','pig','ouv'];
function CC_menuStickyBottom(){
  var nav=document.querySelector('.inputs-nav');
  if(!nav)return 80;
  var topPx=70;
  try{topPx=parseFloat(getComputedStyle(nav).top)||70;}catch(e){}
  return topPx+nav.offsetHeight;
}
function CC_ensureSticky(type){
  var c=CC_gid('CC_sticky_'+type);
  if(!c){
    c=document.createElement('div');
    c.id='CC_sticky_'+type;
    c.className='gp-sticky-head';
    document.body.appendChild(c);
  }
  return c;
}
function CC_updateStickyHeads(){
  if(typeof window==='undefined')return;
  var mb=CC_menuStickyBottom();
  CC_STICKY_TYPES.forEach(function(type){
    var table=CC_gid('CC_tbl_'+type);
    var c=CC_ensureSticky(type);
    if(!table||!table.tHead){c.style.display='none';return;}
    var wrap=table.parentElement;
    var tr=table.getBoundingClientRect();
    var thH=table.tHead.getBoundingClientRect().height;
    if(tr.top<mb-1&&tr.bottom>mb+6){
      var wr=wrap.getBoundingClientRect();
      var cells=table.tHead.rows[0].cells;
      var sig=table.className+'|'+table.offsetWidth+'|'+table.tHead.innerHTML.length;
      for(var i=0;i<cells.length;i++)sig+='|'+cells[i].offsetWidth;
      if(c.getAttribute('data-sig')!==sig){
        var ct=document.createElement('table');
        ct.style.cssText='table-layout:fixed;border-collapse:collapse;width:'+table.offsetWidth+'px;';
        var cg=document.createElement('colgroup');
        var hr=document.createElement('tr');
        // On ne clone QUE les colonnes visibles (largeur > 0). Une cellule masquée
        // (display:none) ne consomme pas de colonne ; cloner les masquées décalerait
        // le mappage colonne↔en-tête et tasserait les titres vers la gauche.
        for(var j=0;j<cells.length;j++){
          var w=cells[j].offsetWidth;
          if(w<=0)continue;
          var col=document.createElement('col');
          col.style.width=w+'px';
          cg.appendChild(col);
          hr.appendChild(cells[j].cloneNode(true));
        }
        var nt=document.createElement('thead');
        nt.appendChild(hr);
        ct.appendChild(cg);
        ct.appendChild(nt);
        c.innerHTML='';
        c.appendChild(ct);
        c.setAttribute('data-sig',sig);
      }
      c.style.top=mb+'px';
      c.style.left=wr.left+'px';
      c.style.width=wr.width+'px';
      c.style.height=thH+'px';
      c.style.display='block';
      if(c.firstChild)c.firstChild.style.transform='translateX('+(-wrap.scrollLeft)+'px)';
    } else {
      c.style.display='none';
    }
  });
}
function CC_initStickyHeads(){
  if(typeof window==='undefined'||!window.addEventListener)return;
  window.addEventListener('scroll',CC_updateStickyHeads,{passive:true});
  window.addEventListener('resize',CC_updateStickyHeads,{passive:true});
  CC_STICKY_TYPES.forEach(function(type){
    var table=CC_gid('CC_tbl_'+type);
    if(table&&table.parentElement)table.parentElement.addEventListener('scroll',CC_updateStickyHeads,{passive:true});
  });
  CC_updateStickyHeads();
}

