var CC_PRODUCT_TEMPLATE_ID=307;
var CC_PRODUCT_VARIANT_ID=482;
function CC_ajouterAuPanier(){
  var metaS=CC_gid('CC_meta_surplus');
  var qty=metaS?parseInt(metaS.textContent,10):0;
  if(!qty||isNaN(qty))return;
  var btn=CC_gid('CC_btnPanier');
  if(btn){btn.disabled=true;btn.textContent='Ajout en cours\u2026';}
  var status=CC_gid('CC_panierStatus');
  fetch('/shop/cart/add',{
    method:'POST',credentials:'include',
    headers:{'Content-Type':'application/json','Accept':'application/json'},
    body:JSON.stringify({jsonrpc:'2.0',method:'call',id:1,params:{
      product_template_id:CC_PRODUCT_TEMPLATE_ID,
      product_id:CC_PRODUCT_VARIANT_ID,
      quantity:qty,add_qty:qty,
      product_custom_attribute_values:[],no_variant_attribute_values:[]
    }})
  }).then(function(r){return r.json();}).then(function(data){
    if(btn){btn.disabled=false;btn.textContent='Ajouter au panier';}
    if(data&&data.error){if(status)status.textContent='\u26a0 Erreur: '+JSON.stringify(data.error);}
    else{if(status)status.innerHTML='\u2713 '+qty+' sacs ajout\u00e9s! <a href="/shop/cart" style="color:#1a1a1a;font-weight:700">Voir le panier \u2192</a>';}
  }).catch(function(e){
    if(btn){btn.disabled=false;btn.textContent='Ajouter au panier';}
    if(status)status.textContent='\u26a0 Erreur r\u00e9seau: '+e.message;
  });
}

