function CC_saveLocal(){
  try{
    var data={
      v:1,ts:Date.now(),
      proj:{no:CC_gid('CC_projNo')?CC_gid('CC_projNo').value:'',nom:CC_gid('CC_projNom')?CC_gid('CC_projNom').value:'',cli:CC_gid('CC_projCli')?CC_gid('CC_projCli').value:'',ent:CC_gid('CC_projEnt')?CC_gid('CC_projEnt').value:'',adr:CC_gid('CC_projAdr')?CC_gid('CC_projAdr').value:'',ville:CC_gid('CC_projVille')?CC_gid('CC_projVille').value:'',prov:CC_gid('CC_projProv')?CC_gid('CC_projProv').value:'',cp:CC_gid('CC_projCP')?CC_gid('CC_projCP').value:'',notes:CC_gid('CC_projNotes')?CC_gid('CC_projNotes').value:''},
      rows:CC_rows,sections:CC_sections,buf:CC_getBuf(),unit:CC_unitSystem,
      takeoff:(typeof window!=='undefined'&&window.GPM_serialize)?window.GPM_serialize():null
    };
    localStorage.setItem(CC_SAVE_KEY,JSON.stringify(data));
    CC_updateSaveLabel();
    var st=CC_gid('CC_saveStatus');if(st){st.textContent='Sauvegard\u00e9 \u2713';setTimeout(function(){st.textContent='';},2500);}
  }catch(e){console.error('[CC] Save fail',e);}
}
function CC_loadLocal(){
  try{
    var raw=localStorage.getItem(CC_SAVE_KEY);
    if(!raw)return false;
    var data=JSON.parse(raw);
    if(!data||!data.rows)return false;
    // Projet
    var p=data.proj||{};
    ['No','Nom','Cli','Ent','Adr','Ville','Prov','CP','Notes'].forEach(function(k){
      var el=CC_gid('CC_proj'+k);
      if(el)el.value=p[k.toLowerCase()]||'';
    });
    // Sections
    if(data.sections&&data.sections.length)CC_sections=data.sections;
    // Rangées
    CC_rows=data.rows;
    // Réassigne des IDs frais et globalement uniques à TOUTES les rangées chargées.
    // Évite les collisions inter-zones (un id réutilisé entre zones faisait que le
    // « -1 » d'une ouverture écrasait l'affichage d'une autre zone via CC_sacs_<id>).
    ['grenier','plafonds','murs','pig','ouv'].forEach(function(z){
      (CC_rows[z]||[]).forEach(function(row){row.id=CC_newRowId();});
    });
    // Buffer
    var buf=data.buf||5;
    ['CC_bufSlider','CC_sBufSlider'].forEach(function(id){var el=CC_gid(id);if(el)el.value=buf;});
    ['CC_bufInput','CC_sBufInput'].forEach(function(id){var el=CC_gid(id);if(el)el.value=buf;});
    var disp=CC_gid('CC_sBufDisplay');if(disp)disp.textContent=buf+'%';
    // Unités — l'app démarre TOUJOURS en pi + po. Si le projet a été sauvegardé en mm,
    // on convertit les dimensions vers l'impérial pour un affichage correct.
    if(data.unit==='mm'){CC_convertAllDims('mm','imp');}
    CC_setUnitSystem('imp',null,true);
    CC_renderSectionsBar();
    CC_renderAllTables();
    // Mesures sur plan (take-off) : segments/surfaces + échelle par page (sans l'image du plan).
    if(data.takeoff&&typeof window!=='undefined'&&window.GPM_restore){try{window.GPM_restore(data.takeoff);}catch(e){}}
    CC_updateSaveLabel(data.ts);
    return true;
  }catch(e){console.error('[CC] Load fail',e);return false;}
}
function CC_updateSaveLabel(ts){
  var el=CC_gid('CC_saveLabel');if(!el)return;
  if(!ts){try{var raw=localStorage.getItem(CC_SAVE_KEY);if(raw){var d=JSON.parse(raw);ts=d.ts;}}catch(e){}}
  if(ts){var dt=new Date(ts);el.innerHTML='Derni\u00e8re sauvegarde&nbsp;: <strong>'+dt.toLocaleString('fr-CA')+'</strong>';}
  else el.textContent='Aucune sauvegarde locale';
}
function CC_hasContent(){
  return Object.keys(CC_rows).some(function(z){return (CC_rows[z]||[]).length>0;});
}
function CC_newProject(){
  if(!confirm('Effacer le projet en cours et repartir de z\u00e9ro\u00a0?'))return;
  CC_rows={grenier:[],plafonds:[],murs:[],pig:[],ouv:[]};
  CC_sections=[{id:'s1',name:'RDC'}];
  ['CC_projNo','CC_projNom','CC_projCli','CC_projEnt','CC_projAdr','CC_projVille','CC_projProv','CC_projCP','CC_projNotes'].forEach(function(id){var el=CC_gid(id);if(el)el.value='';});
  CC_renderSectionsBar();
  CC_seedExampleRows(); // une ligne vierge par section (grenier/plafonds/murs/ouv), comme au 1er chargement
  CC_recalc();
  if(typeof window!=='undefined'&&typeof window.GPM_reset==='function')window.GPM_reset(); // vide aussi la prise de mesure
}
function CC_exportJSON(){
  CC_saveLocal();
  try{
    var raw=localStorage.getItem(CC_SAVE_KEY);
    if(!raw)return;
    var blob=new Blob([raw],{type:'application/json'});
    var a=document.createElement('a');
    a.href=URL.createObjectURL(blob);
    a.download='cellulose-profibcell-'+(CC_gid('CC_projNo')?CC_gid('CC_projNo').value:'projet')+'.json';
    a.click();
  }catch(e){}
}
function CC_importJSON(input){
  var file=input.files[0];if(!file)return;
  var reader=new FileReader();
  reader.onload=function(e){
    try{
      localStorage.setItem(CC_SAVE_KEY,e.target.result);
      CC_loadLocal();
      CC_recalc();
    }catch(ex){alert('Fichier JSON invalide.');}
  };
  reader.readAsText(file);
  input.value='';
}

